window.AUTH=window.AUTH||{};window.AUTH["17-1618"]={"d":"17-1618","id":"2019/17-1618","n":"Bostock v. Clayton County","briefs":[{"k":"petitioner","label":"Brief of petitioner Gerald Lynn Bostock","date":"2019-06-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-1618/104212/20190626161040839_38089%20pdf%20Sutherland%20I%20-%20Brief%20to%20File.pdf","side":"pet","n":93},{"k":"respondent","label":"Brief of respondents Melissa Zarda, et al.","date":"2019-06-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-1618/104155/20190626114351461_17-1623bs.pdf","side":"res","n":71},{"k":"petitioner","label":"Brief of petitioners Altitude Express, Inc., et al.","date":"2019-08-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-1618/112667/20190816164240762_Brief%20for%20Petitioners%20Altitude%20Express%20Inc%20and%20Ray%20Maynard.pdf","side":"pet","n":89},{"k":"respondent","label":"Brief of respondent Clayton County, Georgia","date":"2019-08-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-1618/112668/20190816164820200_38344%20pdf%20Buechner%20Jr.pdf","side":"res","n":107},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-08-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1618/113417/20190823143040818_17-1618bsacUnitedStates.pdf","side":"us","n":68},{"k":"reply","label":"Reply of petitioner Gerald Lynn Bostock","date":"2019-09-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1618/115243/20190910115042307_Bostock%20Reply%20Brief.pdf","side":"pet","n":50}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=232","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Allied-Bruce Terminix Companies, Inc. v. Dobson","cite":"513 U.S. 265","y":1995,"id":"1994/93-1001","sc":1,"sum":"The Court held that the Federal Arbitration Act applied to all disputes involving commerce, and thus the arbitration clause was valid and enforceable.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Bellaver v. Quanex Corp.","cite":"200 F.3d 485","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/200/485/","by":{"0":"26"}},{"t":"case","label":"Bibby v. Philadelphia Coca Cola Bottling Co.","cite":"260 F.3d 257","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/260/257/","op":1,"by":{"0":"26","3":"16","4":"4"}},{"t":"case","label":"Blum v. Gulf Oil Corp.","cite":"597 F.2d 936","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/597/936/","op":2,"by":{"0":"3, 6, 7, 9","1":"48-49","2":"26","3":"passim","4":"4","5":"19"}},{"t":"case","label":"BNSF Ry. Co. v. Loos","cite":"139 S. Ct. 893","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43","3":"58","5":"13, 17"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"0":"18","1":"40","2":"29, 58","3":"50","5":"16"}},{"t":"case","label":"Bonner v. City of Prichard","cite":"661 F.2d 1206","y":1981,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/661/1206/","by":{"0":"6","3":"53"}},{"t":"case","label":"Bostock v. Clayton County, Ga.","cite":"723 F. App’x 964","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/723/964/","by":{"0":"1","3":"5"}},{"t":"case","label":"Bostock v. Clayton County, Ga.","cite":"894 F.3d 1335","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/894/1335/","by":{"0":"1","3":"5"}},{"t":"case","label":"Bostock v. Clayton County, Ga.","cite":"139 S. Ct. 1599","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./139/1599/","sc":1,"by":{"0":"2"}},{"t":"case","label":"Brannum v. Mo. Dep’t of Corr.","cite":"518 F.3d 542","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/518/542/","by":{"0":"56"}},{"t":"case","label":"Cannon v. Univ. of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","3":"53","5":"18"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"CBOCS West, Inc. v. Humphries","cite":"553 U.S. 442","y":2008,"id":"2007/06-1431","sc":1,"sum":"Section 1981 encompasses retaliation claims. The 7-2 decision, written by Justice Stephen Breyer, relied heavily on the concept of stare decisis, or adherence to prior Court decisions, in reaching its conclusion.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Centola v. Potter","cite":"183 F. Supp. 2d 403","y":2002,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/183/403/","by":{"0":"27"}},{"t":"case","label":"Chadwick v. WellPoint, Inc.","cite":"561 F.3d 38","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/561/38/","by":{"0":"26"}},{"t":"case","label":"Christiansen v. Omnicom Group, Inc.","cite":"852 F.3d 195","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/852/195/","by":{"0":"26, 54","4":"26"}},{"t":"case","label":"City of Los Angeles, Dep’t of Water and Power v. Manhart","cite":"435 U.S. 702","y":1978,"id":"1977/76-1810","sc":1,"op":2,"sum":"The Court held that the company’s policy was based on aggregate numbers that are not necessarily true for individuals, which violates the Civil Rights Act prohibition of individual discrimination based purely on gender.","sumSrc":"Oyez","by":{"0":"passim","1":"17, 34-35, 45","2":"14–15, 42–43","3":"passim","4":"20, 21, 23, 24, 26","5":"passim"}},{"t":"case","label":"Clover v. Total Sys. Servs., Inc.","cite":"176 F.3d 1346","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/176/1346/","by":{"0":"56"}},{"t":"case","label":"Connecticut v. Teal","cite":"457 U.S. 440","y":1982,"id":"1981/80-2147","sc":1,"sum":"Petitioners' nondiscriminatory \"bottom line\" does not preclude respondents from establishing a prima facie case nor does it provide petitioners with a defense to such a case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17","1":"37"}},{"t":"case","label":"Cooper Distributing Co., Inc. v. Amana Refrigeration, Inc.","cite":"63 F.3d 262","y":1995,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/63/262/","by":{"0":"35"}},{"t":"case","label":"Crawford v. Metro. Gov’t of Nashville and Davidson Cnty., Tn.","cite":"555 U.S. 271","y":2009,"id":"2008/06-1595","sc":1,"sum":"The Court held that the anti-retaliation provision of Title VII extends to people who participate in an internal investigation, even if they are not speaking on their own initiative.","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"Dawson v. Bumble & Bumble","cite":"398 F.3d 211","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/398/211/","sum":"Explaining that sex stereotype claims can present problems because “ ‘stereotypical notices about how men and women should behave will often necessarily blur into ideas about heterosexuality and homosexuality’ ”.","sumSrc":"brief:0","by":{"0":"51","1":"28"}},{"t":"case","label":"Deffenbaugh-Williams v. Wal-Mart Stores, Inc.","cite":"156 F.3d 581","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/156/581/","sum":"Holding that Title VII prohibits employment discrimination based upon an interracial relationship.","sumSrc":"brief:0","by":{"0":"19","1":"32"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"0":"13","2":"12, 25"}},{"t":"case","label":"E.E.O.C. v. Boh Bros. Constr. Co., L.L.C.","cite":"731 F.3d 444","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/731/444/","by":{"0":"31","1":"25, 29"}},{"t":"case","label":"E.E.O.C. v. Boh Bros. Constr. Co., L.L.C.","cite":"689 F.3d 444","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/689/444/","by":{"0":"26"}},{"t":"case","label":"E.E.O.C. v. Boh Bros. Constr. Co., L.L.C.","cite":"768 F. Supp. 2d 883","y":2011,"court":"E.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/768/883/","by":{"0":"52"}},{"t":"case","label":"E.E.O.C. v. Family Dollar Stores, Inc.","cite":"2008 WL 4098723","y":2008,"court":"N.D. Ga. Aug. 28","op":8,"by":{"0":"53"}},{"t":"case","label":"E.E.O.C. v. Joe’s Stone Crab, Inc.","cite":"220 F.3d 1263","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/220/1263/","by":{"0":"26"}},{"t":"case","label":"Evans v. Ga. Reg’l Hospital","cite":"850 F.3d 1248","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/1248/","op":1,"sum":"Stating that an employee should be given the opportunity to repackage her claim that she was fired for being a lesbian as a “gender nonconformity claim”.","sumSrc":"brief:1","by":{"0":"7, 8, 9, 26","1":"30","2":"45","3":"4, 5, 17","4":"4, 5"}},{"t":"case","label":"Food and Drug Admin. v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"50","2":"25–26, 52","3":"45","5":"4"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. ___","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43","2":"21","5":"22"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T.A.","cite":"557 U.S. 239","y":2009,"id":"2008/08-305","sc":1,"op":1,"sum":"The Court found that the Individuals with Disabilities Education Act (IDEA) can authorize a public school to reimburse a student for private school tuition sought because the student never received special education services at the public school.","sumSrc":"Oyez","by":{"0":"39, 42","3":"51"}},{"t":"case","label":"Fort Stewart Sch. v. Fed. Labor Relations Auth.","cite":"495 U.S. 641","y":1990,"id":"1989/89-65","sc":1,"sum":"The Authority did not err in ruling that petitioner was required to bargain over the Union's proposals.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43, 45"}},{"t":"case","label":"Franchina v. City of Providence","cite":"881 F.3d 32","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/881/32/","by":{"0":"26"}},{"t":"case","label":"Gen. Elec. Co. v. Gilbert","cite":"425 U.S. 125","y":1976,"url":"https://supreme.justia.com/cases/federal/us/425/125/","sc":1,"by":{"0":"34, 36"}},{"t":"case","label":"Gregory v. Ga. Dep’t of Human Res.","cite":"355 F.3d 1277","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/355/1277/","op":2,"by":{"0":"56, 57"}},{"t":"case","label":"Gutierrez v. Ada","cite":"528 U.S. 250","y":2000,"id":"1999/99-51","sc":1,"sum":"The Court held that \"[t]he Guam Organic Act does not require a runoff election when a candidate slate has received a majority of the votes cast for Governor and Lieutenant Governor of the Territory, but not a majority of the number of ballots cast in the simultaneous general election.\" Justice Souter wrote for the Court that an \"obvious reading\" of the law requires only a majority of votes cast in that one specific race, \"Congress did not shift its attention when it used 'any election' unadorned by a gubernatorial reference or other definite modifier.\".","sumSrc":"Oyez","by":{"0":"43","5":"23"}},{"t":"case","label":"Hamm v. Weyauwega Milk Prods., Inc.","cite":"332 F.3d 1058","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/332/1058/","op":1,"sum":"Upholding summary judgment against a plaintiff who was called “girl scout” and mocked for having a “high-pitched” voice because the evidence pointed to the conclusion that he was being discriminated against because of sexual orientation.","sumSrc":"brief:0","by":{"0":"52, 53, 54, 55","1":"28","2":"40, 57","3":"61, 62","4":"4, 24, 27"}},{"t":"case","label":"Hively v. Ivy Tech Cmty. Coll. of Indiana","cite":"853 F.3d 339","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/853/339/","op":6,"ar":2,"sum":"Noting that “[i]t would require considerable calisthenics to remove the ‘sex’ from ‘sexual orientation’ ”.","sumSrc":"brief:0","by":{"0":"passim","1":"7, 32","2":"passim","3":"passim","4":"4, 13, 14, 15, 19, 25"}},{"t":"case","label":"Int’l Union, United Auto., Aerospace & Agr. Implement Workers of Am., UAW v. Johnson Controls, Inc.","cite":"499 U.S. 187","y":1991,"id":"1990/89-1215","sc":1,"sum":"The Court noted that even well intentioned proposals are forbidden if they result in discrimination. Johnson's fetal-protection plan discriminated against women by not requiring their male counterparts to demonstrate proof of medical sterility, despite the fact that lead exposure has also proved hazardous to male reproductive systems.","sumSrc":"Oyez","by":{"0":"16, 41","1":"16, 17, 35","2":"15–16","3":"21, 22, 28, 29","4":"23","5":"8"}},{"t":"case","label":"Jam v. Int’l Fin. Corp.","cite":"139 S. Ct. 759","y":2019,"id":"2018/17-1011","sc":1,"sum":"The International Organizations Immunities Act of 1945 affords international organizations the same immunity from suit that foreign governments enjoy today under the Foreign Sovereign Immunities Act of 1976.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"46","2":"18"}},{"t":"case","label":"Kay v. Independence Blue Cross","cite":"142 F. App’x 48","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/142/48/","sum":"Noting that the harassment included referring to “real men” as opposed to the “fem” plaintiff and assuming that this was evidence of sex stereotyping but nevertheless affirming the district court’s dismissal because other evidence indicated sexual orientation bias.","sumSrc":"brief:0","by":{"0":"49, 52","3":"59, 62"}},{"t":"case","label":"Kimble v. Marvel Entm’t, L.L.C.","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"0":"40, 46"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","2":"21–22, 25, 54"}},{"t":"case","label":"Lawrence v. Texas","cite":"539 U.S. 558","y":2003,"id":"2002/02-102","sc":1,"op":2,"sum":"The Court found that a Texas statute banning consenting homosexual adults from engaging in sexual acts violated the Fourteenth Amendment's guarantee of equal protection.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Lewis v. City of Chicago, Ill.","cite":"560 U.S. 205","y":2010,"id":"2009/08-974","sc":1,"sum":"The Court held that an employee may file a Title VII disparate impact claim within 300 days after their employer executes the allegedly unlawful practice.","sumSrc":"Oyez","by":{"0":"44","1":"42","2":"53","5":"3, 23"}},{"t":"case","label":"Lewis v. Heartland Inns of Am., L.L.C.","cite":"591 F.3d 1033","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/591/1033/","by":{"0":"26","1":"25"}},{"t":"case","label":"Loving v. Virginia","cite":"388 U.S. 1","y":1967,"id":"1966/395","sc":1,"sum":"The Court held that the Fourteenth Amendment prohibits governments from discriminating against individuals on the basis of race.","sumSrc":"Oyez","by":{"0":"passim","1":"8, 35","2":"48–50","3":"8, 40, 41, 43, 44","4":"28","5":"10"}},{"t":"case","label":"McDonnell Douglas Corp. v. Green","cite":"411 U.S. 792","y":1973,"id":"1972/72-490","sc":1,"sum":"The Court held that the findings of the EEOC could not bar a suit that meets the jurisdictional requirements for suing in federal district court. The Court also held that Congress meant to prevent discriminatory hiring practices, not guarantee jobs, so that the complainant in an employment discrimination lawsuit carries the initial burden to present a prima facie case for racial discrimination.","sumSrc":"Oyez","by":{"0":"21","1":"15, 24","2":"18, 53"}},{"t":"case","label":"McLaughlin v. Florida","cite":"379 U.S. 184","y":1964,"id":"1964/11","sc":1,"sum":"The Florida statute denies the equal protection of the laws guaranteed by the Fourteenth Amendment and is invalid. Pp. 184-196. 153 So. 2d 1, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 20"}},{"t":"case","label":"Meritor Sav. Bank, FSB v. Vinson","cite":"477 U.S. 57","y":1986,"id":"1985/84-1979","sc":1,"op":2,"sum":"The Court held that the language of Title VII was \"not limited to 'economic' or 'tangible' discrimination,\" finding that Congress intended \"'to strike at the entire spectrum of disparate treatment of men and women' in employment. . .\" The Court noted that guidelines issued by the EEOC specified that sexual harassment leading to noneconomic injury was a form of sex discrimination prohibited by Title VII.","sumSrc":"Oyez","by":{"0":"passim","1":"43, 44","3":"13, 17, 21, 34","4":"2","5":"2, 14, 15"}},{"t":"case","label":"Newport News Shipbuilding and Dry Dock Co. v. E.E.O.C.","cite":"462 U.S. 669","y":1983,"id":"1982/82-411","sc":1,"ar":2,"sum":"The pregnancy limitation in petitioner's amended health plan discriminates against male employees in violation of § 703(a)(1).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"21, 22, 28","2":"33–34","3":"passim","4":"23","5":"1, 9, 15"}},{"t":"case","label":"Nevada Dep’t of Hum. Res. v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"op":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"22","5":"10"}},{"t":"case","label":"Nichols v. Azteca Rest. Enter., Inc.","cite":"256 F.3d 864","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/256/864/","sum":"Holding that an employee proved a sex-based hostile work environment even though the harasser called him a “faggot” because “the most vulgar name-calling directed at [the plaintiff ] was cast in female terms”.","sumSrc":"brief:0","by":{"0":"26, 53","1":"25","3":"62"}},{"t":"case","label":"Norris v. Diakin Drivetrain Components","cite":"46 F. App’x 344","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/46/344/","sum":"Holding that the plaintiff did not exhaust his same-sex sexual harassment claim by alleging sexual orientation discrimination in his charge and dismissing the case.","sumSrc":"brief:0","by":{"0":"57"}},{"t":"case","label":"North Star Steel Co. v. Thomas","cite":"515 U.S. 29","y":1995,"id":"1994/94-834","sc":1,"ar":1,"sum":"The Court held that State law is the proper source of the limitations period for civil actions brought to enforce WARN. Where a federal statute fails to provide any limitations period for a new cause of action, the Court noted that its longstanding practice has been to borrow the limitations period from the most closely analogous state statute.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Obergefell v. Hodges","cite":"135 S. Ct. 2584","y":2015,"id":"2014/14-556","sc":1,"op":1,"sum":"The Court held that the Fourteenth Amendment requires states to license and recognize same-sex marriage.","sumSrc":"Oyez","by":{"0":"46","2":"48, 57–61"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"op":17,"ar":6,"sum":"Noting that unexpected applications of broad language refect only Congress's “presumed point [to] produce general coverage—not to leave room for courts to recognize ad hoc exceptions”.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"14, 16, 51–52","3":"4, 5, 18, 19, 34","4":"15, 16, 17, 19, 20, 24","5":"1, 4"}},{"t":"case","label":"Parker v. Reema Consulting Servs., Inc.","cite":"915 F.3d 297","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/915/297/","sum":"Holding that an employee could state a claim under Price Waterhouse for discrimination on the basis of conformity to a negative gender stereotype.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Parr v. Woodmen of the World Life Ins. Co.","cite":"791 F.2d 888","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/791/888/","op":1,"sum":"Holding that Title VII prohibits discrimination against a person because of his marriage to or association with a person of a different race.","sumSrc":"brief:0","by":{"0":"19, 20","1":"32"}},{"t":"case","label":"Pension Ben. Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"op":2,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"46","2":"29","3":"48","4":"31","5":"13, 17"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"sum":"Bribery of private employees prohibited by state criminal statutes violates the Travel Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","2":"12","3":"10"}},{"t":"case","label":"Phillips v. Martin Marietta Corp.","cite":"400 U.S. 542","y":1971,"id":"1970/73","sc":1,"op":5,"sum":"A case in which that Court held that, in the absence of evidence that having preschool-age children is demonstrably more relevant to female job performance than to male job performance, a refusal to hire women with preschool-age children violates the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"16","1":"20, 21, 23","2":"33–34","3":"21","4":"22, 23"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"op":7,"ar":6,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"10, 16, 39–42","3":"passim","4":"20, 24","5":"passim"}},{"t":"case","label":"Prowel v. Wise Bus. Forms, Inc.","cite":"579 F.3d 285","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/579/285/","sum":"Noting that “the line between sexual orientation discrimination and discrimination ‘because of sex’ can be difficult to draw”.","sumSrc":"brief:0","by":{"0":"26, 51","1":"29","2":"46","3":"36","4":"26"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"op":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"0":"19, 21, 46","1":"35","2":"15–16, 48","3":"41","4":"31"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Romer v. Evans","cite":"517 U.S. 620","y":1996,"id":"1995/94-1039","sc":1,"sum":"The Court found a Colorado amendment that banned protection from discrimination based on sexual orientation violated the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"46","1":"30","2":"48"}},{"t":"case","label":"Schmedding v. Tnemec Co., Inc.","cite":"187 F.3d 862","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/187/862/","by":{"0":"52","3":"62"}},{"t":"case","label":"Shapiro v. United States","cite":"335 U.S. 1","y":1948,"id":"scdb/1947-110","sc":1,"op":1,"sum":"The plea in bar was properly overruled by the trial court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Smith v. City of Salem, Ohio","cite":"378 F.3d 566","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/378/566/","by":{"0":"26","1":"25"}},{"t":"case","label":"Sutton v. United Air Lines","cite":"527 U.S. 471","y":1999,"id":"1998/97-1943","sc":1,"sum":"This reading is in harmony with the statutory language and history of the ADA because (1) the phrase \"substantially limits\" requires consideration of present, not future or hypothetical, impairment; (2) the ADA calls for individualized assessments of impairment; and (3) Congress found that approximately 43 million Americans were disabled, a number that would be far too low if Congress had meant to include all those with correctable impairments.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Swift v. Countrywide Home Loans, Inc.","cite":"770 F. Supp. 2d 483","y":2011,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/770/483/","by":{"0":"49","3":"59"}},{"t":"case","label":"Swift & Co. v. Wickham","cite":"382 U.S. 111","y":1965,"id":"1965/9","sc":1,"sum":"The three-judge court requirement applies to injunction suits depending directly upon a substantive provision of the' Constitution and does not apply to Supremacy Clause cases involving only federal-state statutory conflicts.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"57"}},{"t":"case","label":"Tetro v. Elliott Popham Pontiac, Oldsmobile, Buick & GMC Trucks, Inc.","cite":"173 F.3d 998","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/173/998/","by":{"0":"19, 20"}},{"t":"case","label":"Texas Dep’t of Hous. and Comm. Affairs v. Inclusive Cmty’s Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"0":"40, 41","2":"26–27","4":"30, 31","5":"18"}},{"t":"case","label":"Tillman v. Wheaton-Haven Recreation Ass’n, Inc.","cite":"410 U.S. 431","y":1973,"id":"1972/71-1136","sc":1,"sum":"Respondent association (Wheaton-Haven) operates a community swimming pool, use of which is limited to white members and their white guests. Under Wheaton-Haven's bylaws, a person residing within a geographic preference area, unlike one living outside that area, needs no endorsement for membership from a current member; receives priority (if the membership is full) over all but those who have first options; and (if …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","1":"40"}},{"t":"case","label":"United States v. Kaley","cite":"579 F.3d 1246","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/1246/","sum":"Noting that “the line between sexual orientation discrimination and discrimination ‘because of sex’ can be difficult to draw”.","sumSrc":"brief:0","by":{"0":"9"}},{"t":"case","label":"United States v. Powell","cite":"469 U.S. 57","y":1984,"id":"1984/83-1307","sc":1,"sum":"There is no reason to vacate respondent's telephone facilitation convictions merely because the verdicts cannot rationally be reconciled.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"57"}},{"t":"case","label":"United States v. Steele","cite":"147 F.3d 1316","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/147/1316/","by":{"0":"9"}},{"t":"case","label":"Univ. of Tx. Sw. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"op":3,"sum":"The Court found that Title VII of the Civil Rights Act of 1964 requires the plaintiff to prove their employer would not have taken an action but for the existence of improper motives.","sumSrc":"Oyez","by":{"0":"25, 49","1":"24, 41","2":"passim","3":"15, 47, 57, 59"}},{"t":"case","label":"Weinberger v. Hynson, Westcott & Dunning, Inc.","cite":"412 U.S. 609","y":1973,"id":"1972/72-394","sc":1,"sum":"The Federal Food, Drug, and Cosmetic Act of 1938, as amended in 1962, establishes a system of premarketing clearance for drugs and prohibits in § 505 (a)the introduction into commerce of any \"new drug\" unless a new drug application (NDA) filed with the Food and Drug Administration (FDA) was effective with respect to such drug. Under the Act procedures were established for filing \"new drug\" applications not only for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48, 51"}},{"t":"case","label":"West v. Gibson","cite":"527 U.S. 212","y":1999,"id":"1998/98-238","sc":1,"sum":"The Court held that the Equal Employment Opportunity Commission possess the legal authority to require federal agencies to pay compensatory damages when they discriminate in violation of Title VII of Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"33, 46","3":"12"}},{"t":"case","label":"Williams v. Wal-Mart Stores, Inc.","cite":"182 F.3d 333","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/182/333/","op":2,"by":{"0":"19"}},{"t":"case","label":"Wisconsin Central Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"op":2,"ar":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"33","1":"42","2":"12, 22, 54","3":"6, 11, 20","5":"3, 4"}},{"t":"case","label":"Zarda v. Altitude Express, Inc.","cite":"883 F.3d 100","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/883/100/","op":6,"sum":"Holding that “the prohibition on associational discrimination applies with equal force to all the classes protected by Title VII, including sex”.","sumSrc":"brief:0","by":{"0":"passim","3":"passim","5":"23"}},{"t":"case","label":"Zuber v. Allen","cite":"396 U.S. 168","y":1969,"id":"1969/25","sc":1,"sum":"Respondent Vermont dairy farmers (\"country\" milk producers) brought this action to invalidate the so-called farm location differential provided for by order of the Secretary of Agriculture as contrary to the Agricultural Marketing Agreement Act of 1937. The effect of the order is to require milk distributors to pay milk producers situated close to milk marketing areas (\"nearby\" farmers) higher prices than are paid …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","3":"48, 49","5":"17"}},{"t":"case","label":"Brief for the United States as Amicus Curiae Supporting Defendants-Appellees, Zarda v. Altitude Express, Inc.","cite":"2017 WL 3277292","op":13,"by":{"0":"20, 40"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"0":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 72","url":"https://www.law.cornell.edu/rules/frcp/rule_72","subs":["(b)"],"by":{"0":"7"}},{"t":"case","label":"Baldwin v. Foxx","cite":"2015 WL 4397641","y":2015,"court":"July 15","op":1,"sum":"Recognizing that the EEOC had “consistently held that discrimination based on sexual orientation is not actionable under Title VII”.","sumSrc":"brief:4","by":{"1":"5","2":"3","4":"4, 5"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Christian Legal Soc’y v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"op":7,"sum":"The Court held that a college's mandate requiring all officially-recognized student organizations be inclusive and welcoming to all students did not violate a group of Christian students' First Amendment rights when the college refused to recognize a student group that required all members to sign a statement of Christian beliefs for membership.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"County of Washington v. Gunther","cite":"452 U.S. 161","y":1981,"id":"1980/80-429","sc":1,"op":3,"sum":"The Bennett Amendment does not restrict Title VIH's prohibition of sex-based wage discrimination to claims for equal pay for \"equal work.\" Rather, claims for sex-based wage discrimination can also be brought under Title VII even though no member of the opposite sex holds an equal but higher paying job, provided that the challenged wage rate is not exempted under the Equal Pay Act's affirmative defenses as to wage …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45","3":"55"}},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"sum":"Relying on Bivens v. Six Unknown Federal Narcotics Agents (1971) and Butz v. Economou (1978), the Court reversed the lower court's conclusions. Both cases affirmed a citizen's right to bring suit against federal officers for constitutional violations. In this case, Passman violated Davis's rights through sexual discrimination.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Deravin v. Kerik","cite":"335 F.3d 195","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/335/195/","by":{"1":"47"}},{"t":"case","label":"DeSantis v. Pacific Tel. & Tel. Co.","cite":"608 F.2d 327","y":1979,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/608/327/","op":1,"by":{"1":"48","2":"26","3":"53","4":"3","5":"20"}},{"t":"case","label":"Dothard v. Rawlinson","cite":"433 U.S. 321","y":1977,"id":"1976/76-422","sc":1,"op":1,"ar":4,"sum":"The Supreme Court held that the height and weight requirements violated Title VII because Rawlinson showed that the requirement excluded 41% of females in the nation, and the Department was unable to show that the requirement was job-related. The “contact position” ban was a bona fide occupational qualification, however, so Title VII did not prohibit it.","sumSrc":"Oyez","by":{"1":"16, 39, 40","2":"55","4":"21, 22"}},{"t":"case","label":"Faragher v. City of Boca Raton","cite":"524 U.S. 775","y":1998,"id":"1997/97-282","sc":1,"sum":"The Court held that an employer is vicariously liable under Title VII of the Civil Rights Act of 1964 for actionable discrimination caused by a supervisor.","sumSrc":"Oyez","by":{"1":"33","5":"14, 15"}},{"t":"case","label":"Griggs v. Duke Power Co.","cite":"401 U.S. 424","y":1971,"id":"1970/124","sc":1,"sum":"After noting that Title VII of the Act intended to achieve equality of employment opportunities, the Court held that Duke's standardized testing requirement prevented a disproportionate number of African-American employees from being hired by, and advancing to higher-paying departments within, the company.","sumSrc":"Oyez","by":{"1":"15, 49"}},{"t":"case","label":"Harris v. Forklift Systems, Inc.","cite":"510 U.S. 17","y":1993,"id":"1993/92-1168","sc":1,"sum":"The Court found that the district court had been wrong to focus on whether or not the harassment had caused \"concrete psychological harm.\" Instead, Justice O'Connor wrote that the court should have focused on whether the conduct was hostile or abusive. \"Certainly Title VII bars conduct that would seriously affect a reasonable person's psychological well being, but the statute is not limited to such conduct.","sumSrc":"Oyez","by":{"1":"37","2":"14","3":"17, 19, 34","4":"17"}},{"t":"case","label":"Holcomb v. Iona Coll.","cite":"521 F.3d 130","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/521/130/","op":1,"by":{"1":"32-33","5":"9"}},{"t":"case","label":"Howell v. N. Cent. Coll.","cite":"320 F. Supp. 2d 717","y":2004,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/320/717/","by":{"1":"28"}},{"t":"case","label":"Miller v. Bank of Am.","cite":"418 F. Supp. 233","y":1976,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./418/233/","sum":"Finding that sexual harassment could not be discrimination because of sex because “[t]he attraction of males to females and females to males is a natural sex phenomenon”.","sumSrc":"brief:1","by":{"1":"43"}},{"t":"case","label":"Penn. Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"op":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"1":"42","5":"4"}},{"t":"case","label":"Phillips v. Martin Marietta Corp.","cite":"411 F.2d 1","y":1969,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/411/1/","op":1,"by":{"1":"20","5":"6, 8"}},{"t":"case","label":"Rene v. MGM Grand Hotel, Inc.","cite":"305 F.3d 1061","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/305/1061/","by":{"1":"29","3":"17"}},{"t":"case","label":"Simonton v. Runyon","cite":"232 F.3d 33","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/232/33/","op":1,"by":{"1":"5, 6","2":"4","3":"16","4":"4, 7"}},{"t":"case","label":"Tetro v. Elliott Popham Pontiac, Oldsmobile, Buick, & GMC Trucks, Inc.","cite":"173 F.3d 988","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/173/988/","by":{"1":"32"}},{"t":"case","label":"Tex. Dep’t of Housing & Comm. Affairs v. Inclusive Comm. Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2507/","sc":1,"sum":"Finding ratification based on unanimous rulings from nine Courts of Appeals that Fair Housing Act permitted disparate impact claims.","sumSrc":"brief:3","by":{"1":"48, 49","3":"52, 53, 54"}},{"t":"case","label":"Tomkins v. Pub. Serv. Elec. & Gas. Co.","cite":"422 F. Supp. 553","y":1976,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./422/553/","by":{"1":"43"}},{"t":"case","label":"Ulane v. Eastern Airlines, Inc.","cite":"742 F.2d 1081","y":1984,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/742/1081/","op":3,"sum":"Concluding that Title VII does not include “sexual orientation” or transsexual status.","sumSrc":"brief:2","by":{"1":"49","2":"26, 28","3":"53","4":"4"}},{"t":"case","label":"Union Bank v. Wolas","cite":"502 U.S. 151","y":1991,"id":"1991/90-1491","sc":1,"sum":"During the 90-day period preceding its filing of a petition under Chapter 7 of the Bankruptcy Code, ZZZZ Best Co., Inc. (Debtor) made two interest payments and paid a loan commitment fee on its long-term debt to petitioner, Union Bank (Bank). After he was appointed trustee of the Debtor's estate, respondent Wolas filed a complaint against the Bank to recover those payments as voidable preferences under 11 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"United States v. Wise","cite":"370 U.S. 405","y":1962,"id":"1961/488","sc":1,"sum":"A corporate officer is subject to prosecution under § 1 of the Sherman Act whenever he knowingly participates in effecting an illegal contract, combination or conspiracy-be he one who authorizes, orders or helps to perpetrate the crime-regardless of whether he is acting in a representative capacity.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Vill. of Freeport v. Barrella","cite":"814 F.3d 594","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/814/594/","by":{"1":"47"}},{"t":"case","label":"Weeks v. Southern Bell Tel. & Tel. Co.","cite":"408 F.2d 228","y":1969,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/408/228/","sum":"Holding that the idea that women are not fitted for “strenuous, dangerous, obnoxious, boring, or unromantic tasks” could not justify excluding all women from the job of “switchman”.","sumSrc":"brief:1","by":{"1":"23"}},{"t":"case","label":"Williamson v. A.G. Edwards & Sons, Inc.","cite":"876 F.2d 69","y":1989,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/876/69/","op":1,"by":{"1":"48","2":"26","3":"16, 53","4":"3","5":"20"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 1982","url":"https://www.law.cornell.edu/uscode/text/42/1982","by":{"1":"40"}},{"t":"usc","label":"42 U.S.C. § 2000a","url":"https://www.law.cornell.edu/uscode/text/42/2000a","subs":["(a)"],"by":{"1":"33"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","stext":{"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","paras":[[0,"No person in the United States shall, on the ground of race, color, or national origin, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","tname":"The Public Health and Welfare","by":{"1":"33"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(k)","(b)"],"stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":23,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"1":"21","2":"31, 47, 53","3":"23, passim","4":"passim, 2, 15, 2, 33"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)","(e)","(m)","(a)(1)","(h)","(a)(2)","(k)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"1":"passim, passim, 15-16, 34, 16-17, 24, 37","2":"passim","3":"26, 59, 13, 23, 55, 52, 58, 59","4":"2, 3, 12, 32, 26, 32"}},{"t":"law","label":"Pub. L. No. 102-166","url":"https://www.govinfo.gov/link/statute/105/1071","by":{"1":"17","3":"passim","4":"3"}},{"t":"reg","label":"29 C.F.R. § 1604.2","url":"https://www.ecfr.gov/current/title-29/section-1604.2","subs":["(a)(1)"],"by":{"1":"16"}},{"t":"case","label":"Tr. of Oral Arg., Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"op":2,"sum":"The Court found that the proponents of California's same-sex marriage ban (Proposition 8) do not have standing to appeal the decision that made Proposition 8 unconstitutional.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"op":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"2":"19, 25"}},{"t":"case","label":"American Legion v. American Humanist Association","cite":"139 S. Ct. 2067","y":2019,"id":"2018/17-1717","sc":1,"op":1,"sum":"The Court held that the display and maintenance of a large memorial cross by a local government does not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"60"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"19–20, 24–25, 59–60","3":"55","5":"22"}},{"t":"case","label":"Bauer v. Lynch","cite":"812 F.3d 340","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/812/340/","by":{"2":"56","3":"34","4":"18"}},{"t":"case","label":"Beech Aircraft Corp. v. Rainey","cite":"488 U.S. 153","y":1988,"id":"1988/87-981","sc":1,"sum":"Respondents' spouses, a Navy flight instructor and her student, were killed when, during training exercises, their Navy aircraft banked sharply to avoid another plane, lost altitude, and crashed. At the trial of respondents' product liability suit against petitioners, the companies which manufactured and serviced the plane in question, the only seriously disputed issue was whether the crash was caused by pilot error …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Board of Governors of Federal Reserve System v. Dimension Financial Corp.","cite":"474 U.S. 361","y":1986,"id":"1985/84-1274","sc":1,"sum":"The Board did not act within its statutory authority in defining \"banks\" as it did.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"vi Brown v. Board of Education","cite":"347 U.S. 483","y":1954,"id":"1940-1955/347us483","sc":1,"op":14,"sum":"The Court decided that the \"separate but equal\" standards of racial segregation were unconstitutional, paving the way for the Civil Rights Movement and national desegregation.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Dillon v. Frank","cite":"1992 WL 5436","y":1992,"court":"6th Cir. Jan. 15","by":{"2":"31"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"135 S. Ct. 2028","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2028/","sc":1,"sum":"Finding ratification based on unanimous rulings from nine Courts of Appeals that Fair Housing Act permitted disparate impact claims.","sumSrc":"brief:3","by":{"2":"15, 39, 44","3":"32, 47"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19, 22, 59"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"2":"26","3":"44","5":"21"}},{"t":"case","label":"Espinoza v. Farah Manufacturing Co.","cite":"414 U.S. 86","y":1973,"id":"1973/72-671","sc":1,"ar":1,"sum":"An employer's refusal to hire a person because he is not a United States citizen does not constitute' employment discrimination on the basis of 'national origin\" in violation of § 703.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9, 22–23, 32, 45","3":"32, 57","5":"7"}},{"t":"case","label":"Etsitty v. Utah Transit Authority","cite":"502 F.3d 1215","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/502/1215/","op":1,"by":{"2":"55"}},{"t":"case","label":"vii Federal Maritime Commission v. Seatrain Lines, Inc.","cite":"411 U.S. 726","y":1973,"id":"1972/71-1647","sc":1,"sum":"In enacting § 15 of the Shipping Act, 1916, Congress conferred on the Federal Maritime Commission (FMC) the power to exempt 'from the antitrust laws agreements, or those portions of agreements, between carriers that create an ongoing arrangement in which both parties undertake continuing responsibilities, and which therefore necessitate continuous FMC supervision, but not onetime acquisition-of-assets agreements …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Flood v. Kuhn","cite":"407 U.S. 258","y":1972,"id":"1971/71-32","sc":1,"sum":"He also cited Toolson , where the Court specifically held that the business of holding public baseball games for profit between professional clubs was not within the scope of federal antitrust laws. Justice Blackmun also noted that Federal Baseball and Toolson were frequently and favorably cited in other cases to establish the uniqueness of baseball’s exemption.","sumSrc":"Oyez","by":{"2":"29","5":"16"}},{"t":"case","label":"General Electric Co. v. Gilbert","cite":"429 U.S. 125","y":1976,"id":"1975/74-1589","sc":1,"op":1,"sum":"The Court held that employers have the right to exclude any condition from a disability plan with a reasonable basis.","sumSrc":"Oyez","by":{"2":"31","4":"2, 32"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"2":"25","3":"44, 45"}},{"t":"case","label":"Gross v. FBL Financial Services, Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"op":2,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"2":"13, 18, 46","3":"57"}},{"t":"case","label":"Hazen Paper Co. v. Biggins","cite":"507 U.S. 604","y":1993,"id":"1992/91-1600","sc":1,"sum":"The Supreme Court held that interfering with an employee’s pension does not automatically violate the ADEA, though it is a clear ERISA violation. While older employees may have more years of service, age and years of service are independent of each other. On remand, the court of appeals should reconsider whether there is sufficient evidence to support an ADEA violation independent of the pension interference.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Heckler v. Day","cite":"467 U.S. 104","y":1984,"id":"1983/82-1371","sc":1,"sum":"In a 5-to-4 opinion, the Court held that Congress already considered and expressly rejected the imposition of mandatory disability dispute-resolution deadlines. Such deadlines, according to congressional reports, would subordinate quality of service to timeliness.","sumSrc":"Oyez","by":{"2":"29","3":"50","5":"16"}},{"t":"case","label":"International Brotherhood of Teamsters v. United States","cite":"431 U.S. 324","y":1977,"id":"1976/75-636","sc":1,"op":13,"sum":"The United States instituted this litigation under Title VII of the Civil Rights Act of 1964 against petitioners, a nationwide common carrier of motor freight, and a union representing a large group of the company's employees. The Government alleged that the company had engaged in a pattern or practice of discriminating against Negroes and Spanishsurnamed persons (hereinafter sometimes collectively \"minority …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Iselin v. United States","cite":"270 U.S. 245","y":1926,"id":"scdb/1925-076","sc":1,"sum":"1. Par. 3 of § 800(a) of Revenue Act of 1918, laying taxes on theater and opera tickets sold at newstands, hotels, etc., for more than the “established price” at the ticket office of the theater or opera house, held inapplicable to sale by a stockholder of box tickets, issued as an incident of his investment in an opera house company, which were not sold at the box-office and for which there was no established price.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Jespersen v. Harrah’s Operating Co., Inc.","cite":"444 F.3d 1104","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/1104/","by":{"2":"56","3":"34","4":"18"}},{"t":"case","label":"Johnson v. Transportation Agency, Santa Clara County","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"op":2,"ar":1,"sum":"The Court affirmed the promotion procedures of the Agency. Justice Brennan argued that it was not unreasonable to consider sex as one factor among many in making promotion decisions, and that the Agency's actions did not create an absolute barrier to the advancement of men (a quota system did not exist).","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"2":"27","3":"51","4":"30, 31, 32","5":"18"}},{"t":"case","label":"National Federation of Independent Business v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"2":"59"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"op":2,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21","3":"6, 10, 11"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"sum":"The Court ruled that to recover restitution, either the government or the victim must establish a causal relationship between the defendant's conduct and the victim's harm or damages.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Reed v. Reed","cite":"404 U.S. 71","y":1971,"id":"1971/70-4","sc":1,"sum":"A case in which the Court established the unconstitutionality of the Idaho Probate Code that stated \"males must be preferred to females\" when appointing administrators of estates.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Roberts v. U.S. Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Schuette v. BAMN","cite":"572 U.S. 291","y":2014,"id":"2013/12-682","sc":1,"sum":"The Court held that the judiciary did not have standing to overturn the state constitutional amendment regarding affirmative action in school admissions.","sumSrc":"Oyez","by":{"2":"45–46"}},{"t":"case","label":"Staub v. Proctor Hospital","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"2":"38","3":"32"}},{"t":"case","label":"Texas Department of Community Affairs v. Burdine","cite":"450 U.S. 248","y":1981,"id":"1980/79-1764","sc":1,"sum":"A case that held that the defendant bears the burden of proof to provide nondiscriminatory reasons for termination after a former employee has proven a prima facie case that the termination violated the Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"2":"34","3":"27","4":"16"}},{"t":"case","label":"United Air Lines, Inc. v. Evans","cite":"431 U.S. 553","y":1977,"id":"1976/76-333","sc":1,"sum":"Where respondent female flight attendant failed to file a timely claim against petitioner airline for violation of Title VII of the Civil Rights Act of 1964 when her employment was termnated m 1968 pursuant to a later invalidated policy because she got married, petitioner held not to commit a present, continuing violation of Title VII by refusing to credit respondent, after rehning her in 1972, with pre-1972 …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20","3":"55","5":"22"}},{"t":"case","label":"United States v. Virginia","cite":"518 U.S. 515","y":1996,"id":"1995/94-1941","sc":1,"op":1,"sum":"The Court found that the Virginia Military Institute's policy of only admitting and serving males was unconstitutional.","sumSrc":"Oyez","by":{"2":"49, 55–56","3":"35","4":"29"}},{"t":"case","label":"U.S. Postal Service Board of Governors v. Aikens","cite":"460 U.S. 711","y":1983,"id":"1982/81-1044","sc":1,"op":1,"sum":"By framing the issue here in terms of whether a prima facie case is established by an employee's showing only that he was black, that he applied for a promotion for which he possessed the minimum qualifications, and that the employer selected a nonminority applicant, the parties and the Court of Appeals have unnecessarily evaded the ultimate question of discrimination vel non. By establishing a prima facie case, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Vickers v. Fairfield Medical Center","cite":"453 F.3d 757","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/453/757/","by":{"2":"41","3":"16, 36"}},{"t":"case","label":"Watson v. Fort Worth Bank & Trust","cite":"487 U.S. 977","y":1988,"id":"1987/86-6139","sc":1,"op":1,"sum":"The judgment is vacated, and the case is remanded. 798 F. 2d 791, vacated and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts 1, II-A, II-B, and III, concluding that disparate impact analysis may be applied to a subjective or discretionary promotion system. Pp. 985-991, 999-1000.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Whitman v. American Trucking Associations","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"op":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"2":"26","3":"44","5":"4"}},{"t":"case","label":"xii Wittmer v. Phillips 66 Co.","cite":"915 F.3d 328","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/915/328/","op":1,"sum":"Observing that “under Price Waterhouse, sex stereotyping is actionable only to the extent it provides evidence of favoritism of one sex over the other”.","sumSrc":"brief:4","by":{"2":"passim","3":"passim","4":"15, 18, 24"}},{"t":"usc","label":"8 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/8/1401","by":{"2":"32"}},{"t":"usc","label":"18 U.S.C. § 249","url":"https://www.law.cornell.edu/uscode/text/18/249","subs":["(a)(2)","(a)(2)(A)","(c)(4)"],"stext":{"head":"§249. Hate crime acts","paras":[[0,"(a) In General.—"],[1,"(1) Offenses involving actual or perceived race, color, religion, or national origin.—Whoever, whether or not acting under color of law, willfully causes bodily injury to any person or, through the use of fire, a firearm, a dangerous weapon, or an explosive or incendiary device, attempts to cause bodily injury to any person, because of the actual or perceived race, color, religion, or national origin of any person—"],[2,"(A) shall be imprisoned not more than 10 years, fined in accordance with this title, or both; and"],[2,"(B) shall be imprisoned for any term of years or for life, fined in accordance with this title, or both, if—"],[3,"(i) death results from the offense; or"],[3,"(ii) the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill."],[1,"(2) Offenses involving actual or perceived religion, national origin, gender, sexual orientation, gender identity, or disability.—"],[2,"(A) In general.—Whoever, whether or not acting under color of law, in any circumstance described in subparagraph (B) or paragraph (3), willfully causes bodily injury to any person or, through the use of fire, a firearm, a dangerous weapon, or an explosive or incendiary device, attempts to cause bodily injury to any person, because of the actual or perceived religion, national origin, gender, sexual orientation, gender identity, or disability of any person—"],[3,"(i) shall be imprisoned not more than 10 years, fined in accordance with this title, or both; and"],[3,"(ii) shall be imprisoned for any term of years or for life, fined in accordance with this title, or both, if—"],[4,"(I) death results from the offense; or"],[4,"(II) the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill."],[2,"(B) Circumstances described.—For purposes of subparagraph (A), the circumstances described in this subparagraph are that—"],[3,"(i) the conduct described in subparagraph (A) occurs during the course of, or as the result of, the travel of the defendant or the victim—"],[4,"(I) across a State line or national border; or"],[4,"(II) using a channel, facility, or instrumentality of interstate or foreign commerce;"],[3,"(ii) the defendant uses a channel, facility, or instrumentality of interstate or foreign commerce in connection with the conduct described in subparagraph (A);"],[3,"(iii) in connection with the conduct described in subparagraph (A), the defendant employs a firearm, dangerous weapon, explosive or incendiary device, or other weapon that has traveled in interstate or foreign commerce; or"],[3,"(iv) the conduct described in subparagraph (A)—"],[4,"(I) interferes with commercial or other economic activity in which the victim is engaged at the time of the conduct; or"],[4,"(II) otherwise affects interstate or foreign commerce."],[1,"(3) Offenses occurring in the special maritime or territorial jurisdiction of the united states.—Whoever, within the special maritime or territorial jurisdiction of the United States, engages in conduct described in paragraph (1) or in paragraph (2)(A) (without regard to whether that conduct occurred in a circumstance described in paragraph (2)(B)) shall be subject to the same penalties as prescribed in those paragraphs."],[1,"(4) Guidelines.—All prosecutions conducted by the United States under this section shall be undertaken pursuant to guidelines issued by the Attorney General, or the designee of the Attorney General, to be included in the United States Attorneys' Manual that shall establish neutral and objective criteria for determining whether a crime was committed because of the actual or perceived status of any person."],[1,"(5) Lynching.—Whoever conspires to commit any offense under paragraph (1), (2), or (3) shall, if death or serious bodily injury (as defined in section 2246 of this title) results from the offense, be imprisoned for not more than 30 years, fined in accordance with this title, or both."],[1,"(6) Other conspiracies.—Whoever conspires to commit any offense under paragraph (1), (2), or (3) shall, if death or serious bodily injury (as defined in section 2246 of this title) results from the offense, or if the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill, be imprisoned for not more than 30 years, fined in accordance with this title, or both."],[0,"(b) Certification Requirement.—"],[1,"(1) In general.—No prosecution of any offense described in this subsection may be undertaken by the United States, except under the certification in writing of the Attorney General, or a designee, that—"],[2,"(A) the State does not have jurisdiction;"],[2,"(B) the State has requested that the Federal Government assume jurisdiction;"],[2,"(C) the verdict or sentence obtained pursuant to State charges left demonstratively unvindicated the Federal interest in eradicating bias-motivated violence; or"],[2,"(D) a prosecution by the United States is in the public interest and necessary to secure substantial justice."],[1,"(2) Rule of construction.—Nothing in this subsection shall be construed to limit the authority of Federal officers, or a Federal grand jury, to investigate possible violations of this section."],[0,"(c) Definitions.—In this section—"],[1,"(1) the term \"bodily injury\" has the meaning given such term in section 1365(h)(4) of this title, but does not include solely emotional or psychological harm to the victim;"],[1,"(2) the term \"explosive or incendiary device\" has the meaning given such term in section 232 of this title;"],[1,"(3) the term \"firearm\" has the meaning given such term in section 921(a) of this title;"],[1,"(4) the term \"gender identity\" means actual or perceived gender-related characteristics; and"],[1,"(5) the term \"State\" includes the District of Columbia, Puerto Rico, and any other territory or possession of the United States."],[0,"(d) Statute of Limitations.—"],[1,"(1) Offenses not resulting in death.—Except as provided in paragraph (2), no person shall be prosecuted, tried, or punished for any offense under this section unless the indictment for such offense is found, or the information for such offense is instituted, not later than 7 years after the date on which the offense was committed."],[1,"(2) Death resulting offenses.—An indictment or information alleging that an offense under this section resulted in death may be found or instituted at any time without limitation."],[0,"(e) Supervised Release.—If a court includes, as a part of a sentence of imprisonment imposed for a violation of subsection (a), a requirement that the defendant be placed on a term of supervised release after imprisonment under section 3583, the court may order, as an explicit condition of supervised release, that the defendant undertake educational classes or community service directly related to the community harmed by the defendant's offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/249?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§249. Hate crime acts","tname":"Crimes and Criminal Procedure","by":{"2":"18","3":"56","4":"14, 14"}},{"t":"usc","label":"20 U.S.C. § 1092","url":"https://www.law.cornell.edu/uscode/text/20/1092","subs":["(f)(1)(F)(ii)"],"stext":{"head":"§1092. Institutional and financial assistance information for students","paras":[[0,"(a) Information dissemination activities"],[0,"(1) Each eligible institution participating in any program under this subchapter shall carry out information dissemination activities for prospective and enrolled students (including those attending or planning to attend less than full time) regarding the institution and all financial assistance under this subchapter. The information required by this section shall be produced and be made readily available upon request, through appropriate publications, mailings, and electronic media, to an enrolled student and to any prospective student. Each eligible institution shall, on an annual basis, provide to all enrolled students a list of the information that is required to be provided by institutions to students by this section and section 444 of the General Education Provisions Act [20 U.S.C. 1232g] (commonly known as the \"Family Educational Rights and Privacy Act of 1974\"), together with a statement of the procedures required to obtain such information. The information required by this section shall accurately describe—"],[1,"(A) the student financial assistance programs available to students who enroll at such institution;"],[1,"(B) the methods by which such assistance is distributed among student recipients who enroll at such institution;"],[1,"(C) any means, including forms, by which application for student financial assistance is made and requirements for accurately preparing such application;"],[1,"(D) the rights and responsibilities of students receiving financial assistance under this subchapter;"],[1,"(E) the cost of attending the institution, including (i) tuition and fees, (ii) books and supplies, (iii) estimates of typical student room and board costs or typical commuting costs, and (iv) any additional cost of the program in which the student is enrolled or expresses a specific interest;"],[1,"(F) a statement of—"],[2,"(i) the requirements of any refund policy with which the institution is required to comply;"],[2,"(ii) the requirements under section 1091b of this title for the return of grant or loan assistance provided under this subchapter; and"],[2,"(iii) the requirements for officially withdrawing from the institution;"],[1,"(G) the academic program of the institution, including (i) the current degree programs and other educational and training programs, (ii) the instructional, laboratory, and other physical plant facilities which relate to the academic program, (iii) the faculty and other instructional personnel, and (iv) any plans by the institution for improving the academic program of the institution;"],[1,"(H) each person designated under subsection (c) of this section, and the methods by which and locations in which any person so designated may be contacted by students and prospective students who are seeking information required by this subsection;"],[1,"(I) special facilities and services available to students with disabilities;"],[1,"(J) the names of associations, agencies, or governmental bodies which accredit, approve, or license the institution and its programs, and the procedures under which any current or prospective student may obtain or review upon request a copy of the documents describing the institution's accreditation, approval, or licensing;"],[1,"(K) the standards which the student must maintain in order to be considered to be making satisfactory progress, pursuant to section 1091(a)(2) of this title;"],[1,"(L) the completion or graduation rate of certificate- or degree-seeking, full-time, undergraduate students entering such institutions;"],[1,"(M) the terms and conditions of the loans that students receive under parts B, D, and E;"],[1,"(N) that enrollment in a program of study abroad approved for credit by the home institution may be considered enrollment in the home institution for purposes of applying for Federal student financial assistance;"],[1,"(O) the campus crime report prepared by the institution pursuant to subsection (f), including all required reporting categories;"],[1,"(P) institutional policies and sanctions related to copyright infringement, including—"],[2,"(i) an annual disclosure that explicitly informs students that unauthorized distribution of copyrighted material, including unauthorized peer-to-peer file sharing, may subject the students to civil and criminal liabilities;"],[2,"(ii) a summary of the penalties for violation of Federal copyright laws; and"],[2,"(iii) a description of the institution's policies with respect to unauthorized peer-to-peer file sharing, including disciplinary actions that are taken against students who engage in unauthorized distribution of copyrighted materials using the institution's information technology system;"],[1,"(Q) student body diversity at the institution, including information on the percentage of enrolled, full-time students who—"],[2,"(i) are male;"],[2,"(ii) are female;"],[2,"(iii) receive a Federal Pell Grant; and"],[2,"(iv) are a self-identified member of a major racial or ethnic group;"],[1,"(R) the placement in employment of, and types of employment obtained by, graduates of the institution's degree or certificate programs, gathered from such sources as alumni surveys, student satisfaction surveys, the National Survey of Student Engagement, the Community College Survey of Student Engagement, State data systems, or other relevant sources;"],[1,"(S) the types of graduate and professional education in which graduates of the institution's four-year degree programs enrolled, gathered from such sources as alumni surveys, student satisfaction surveys, the National Survey of Student Engagement, State data systems, or other relevant sources;"],[1,"(T) the fire safety report prepared by the institution pursuant to subsection (i);"],[1,"(U) the retention rate of certificate- or degree-seeking, first-time, full-time, undergraduate students entering such institution; and"],[1,"(V) institutional policies regarding vaccinations."],[0,"(2) For the purpose of this section, the term \"prospective student\" means any individual who has contacted an eligible institution requesting information concerning admission to that institution."],[0,"(3) In calculating the completion or graduation rate under subparagraph (L) of paragraph (1) of this subsection or under subsection (e), a student shall be counted as a completion or graduation if, within 150 percent of the normal time for completion of or graduation from the program, the student has completed or graduated from the program, or enrolled in any program of an eligible institution for which the prior program provides substantial preparation. The information required to be disclosed under such subparagraph—"],[1,"(A) shall be made available by July 1 each year to enrolled students and prospective students prior to the students enrolling or entering into any financial obligation; and"],[1,"(B) shall cover the one-year period ending on August 31 of the preceding year."],[0,"(4) For purposes of this section, institutions may—"],[1,"(A) exclude from the information disclosed in accordance with subparagraph (L) of paragraph (1) the completion or graduation rates of students who leave school to serve in the Armed Forces, on official church missions, or with a recognized foreign aid service of the Federal Government; or"],[1,"(B) in cases where the students described in subparagraph (A) represent 20 percent or more of the certificate- or degree-seeking, full-time, undergraduate students at the institution, recalculate the completion or graduation rates of such students by excluding from the calculation described in paragraph (3) the time period during which such students were not enrolled due to their service in the Armed Forces, on official church missions, or with a recognized foreign aid service of the Federal Government."],[0,"(5) The Secretary shall permit any institution of higher education that is a member of an athletic association or athletic conference that has voluntarily published completion or graduation rate data or has agreed to publish data that, in the opinion of the Secretary, is substantially comparable to the information required under this subsection, to use such data to satisfy the requirements of this subsection."],[0,"(6) Each institution may provide supplemental information to enrolled and prospective students showing the completion or graduation rate for students described in paragraph (4) or for students transferring into the institution or information showing the rate at which students transfer out of the institution."],[0,"(7)(A)(i) Subject to clause (ii), the information disseminated under paragraph (1)(L), or reported under subsection (e), shall be disaggregated by gender, by each major racial and ethnic subgroup, by recipients of a Federal Pell Grant, by recipients of a loan made under part B or D (other than a loan made under section 1078–8 of this title or a Federal Direct Unsubsidized Stafford Loan) who did not receive a Federal Pell Grant, and by recipients of neither a Federal Pell Grant nor a loan made under part B or D (other than a loan made under section 1078–8 of this title or a Federal Direct Unsubsidized Stafford Loan), if the number of students in such subgroup or with such status is sufficient to yield statistically reliable information and reporting will not reveal personally identifiable information about an individual student. If such number is not sufficient for such purposes, then the institution shall note that the institution enrolled too few of such students to so disclose or report with confidence and confidentiality."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1092?type=usc&year=mostrecent&link-type=html"},"head":"§1092. Institutional and financial assistance information for students","tname":"Education","by":{"2":"18","3":"56"}},{"t":"usc","label":"34 U.S.C. § 12291","url":"https://www.law.cornell.edu/uscode/text/34/12291","subs":["(b)(13)(A)"],"stext":{"head":"§12291. Definitions and grant provisions","paras":[[0,"(a) Definitions"],[0,"In this subchapter, for the purpose of grants authorized under this subchapter:"],[0,"(1) Abuse in later life"],[1,"The term \"abuse in later life\"—"],[2,"(A) means—"],[3,"(i) neglect, abandonment, economic abuse, or willful harm of an adult aged 50 or older by an individual in an ongoing relationship of trust with the victim; or"],[3,"(ii) domestic violence, dating violence, sexual assault, or stalking of an adult aged 50 or older by any individual; and"],[2,"(B) does not include self-neglect."],[0,"(2) Alaska Native village"],[1,"The term \"Alaska Native village\" has the same meaning given such term in the Alaska Native Claims Settlement Act (43 U.S.C. 1601 et seq.)."],[0,"(3) Child abuse and neglect"],[1,"The term \"child abuse and neglect\" means any recent act or failure to act on the part of a parent or caregiver with intent to cause death, serious physical or emotional harm, sexual abuse, or exploitation, or an act or failure to act which presents an imminent risk of serious harm to an unemancipated minor. This definition shall not be construed to mean that failure to leave an abusive relationship, in the absence of other action constituting abuse or neglect, is itself abuse or neglect."],[0,"(4) Child maltreatment"],[1,"The term \"child maltreatment\" means the physical or psychological abuse or neglect of a child or youth, including sexual assault and abuse."],[0,"(5) Community-based organization"],[1,"The term \"community-based organization\" means a nonprofit, nongovernmental, or tribal organization that serves a specific geographic community that—"],[2,"(A) focuses primarily on domestic violence, dating violence, sexual assault, or stalking;"],[2,"(B) has established a specialized culturally specific program that addresses domestic violence, dating violence, sexual assault, or stalking;"],[2,"(C) has a primary focus on underserved populations (and includes representatives of these populations) and domestic violence, dating violence, sexual assault, or stalking; or"],[2,"(D) obtains expertise, or shows demonstrated capacity to work effectively, on domestic violence, dating violence, sexual assault, and stalking through collaboration."],[0,"(6) Court-based personnel; court-related personnel"],[1,"The terms \"court-based personnel\" and \"court-related personnel\" mean individuals working in the court, whether paid or volunteer, including—"],[2,"(A) clerks, special masters, domestic relations officers, administrators, mediators, custody evaluators, guardians ad litem, lawyers, negotiators, probation, parole, interpreters, victim assistants, victim advocates, and judicial, administrative, or any other professionals or personnel similarly involved in the legal process;"],[2,"(B) court security personnel;"],[2,"(C) personnel working in related supplementary offices or programs (such as child support enforcement); and"],[2,"(D) any other court-based or community-based personnel having responsibilities or authority to address domestic violence, dating violence, sexual assault, or stalking in the court system."],[0,"(7) Courts"],[1,"The term \"courts\" means any civil or criminal, tribal, and Alaska Native Village, Federal, State, local or territorial court having jurisdiction to address domestic violence, dating violence, sexual assault or stalking, including immigration, family, juvenile, and dependency courts, and the judicial officers serving in those courts, including judges, magistrate judges, commissioners, justices of the peace, or any other person with decisionmaking authority."],[0,"(8) Culturally specific"],[1,"The term \"culturally specific\" means primarily directed toward racial and ethnic minority groups (as defined in section 1707(g) of the Public Health Service Act (42 U.S.C. 300u–6(g)).1"],[0,"(9) Culturally specific services"],[1,"The term \"culturally specific services\" means community-based services that include culturally relevant and linguistically specific services and resources to culturally specific communities."],[0,"(10) Dating partner"],[1,"The term \"dating partner\" refers to a person who is or has been in a social relationship of a romantic or intimate nature with the abuser, and where the existence of such a relationship shall be determined based on a consideration of—"],[2,"(A) the length of the relationship;"],[2,"(B) the type of relationship; and"],[2,"(C) the frequency of interaction between the persons involved in the relationship."],[0,"(11) Dating violence"],[1,"The term \"dating violence\" means violence committed by a person—"],[2,"(A) who is or has been in a social relationship of a romantic or intimate nature with the victim; and"],[2,"(B) where the existence of such a relationship shall be determined based on a consideration of the following factors:"],[3,"(i) The length of the relationship."],[3,"(ii) The type of relationship."],[3,"(iii) The frequency of interaction between the persons involved in the relationship."],[0,"(12) Domestic violence"],[1,"The term \"domestic violence\" includes felony or misdemeanor crimes committed by a current or former spouse or intimate partner of the victim under the family or domestic violence laws of the jurisdiction receiving grant funding and, in the case of victim services, includes the use or attempted use of physical abuse or sexual abuse, or a pattern of any other coercive behavior committed, enabled, or solicited to gain or maintain power and control over a victim, including verbal, psychological, economic, or technological abuse that may or may not constitute criminal behavior, by a person who—"],[2,"(A) is a current or former spouse or intimate partner of the victim, or person similarly situated to a spouse of the victim;"],[2,"(B) is cohabitating, or has cohabitated, with the victim as a spouse or intimate partner;"],[2,"(C) shares a child in common with the victim; or"],[2,"(D) commits acts against a youth or adult victim who is protected from those acts under the family or domestic violence laws of the jurisdiction."],[0,"(13) Economic abuse"],[1,"The term \"economic abuse\", in the context of domestic violence, dating violence, and abuse in later life, means behavior that is coercive, deceptive, or unreasonably controls or restrains a person's ability to acquire, use, or maintain economic resources to which they are entitled, including using coercion, fraud, or manipulation to—"],[2,"(A) restrict a person's access to money, assets, credit, or financial information;"],[2,"(B) unfairly use a person's personal economic resources, including money, assets, and credit, for one's own advantage; or"],[2,"(C) exert undue influence over a person's financial and economic behavior or decisions, including forcing default on joint or other financial obligations, exploiting powers of attorney, guardianship, or conservatorship, or failing or neglecting to act in the best interests of a person to whom one has a fiduciary duty."],[0,"(14) Elder abuse"],[1,"The term \"elder abuse\" means any action against a person who is 50 years of age or older that constitutes the willful—"],[2,"(A) infliction of injury, unreasonable confinement, intimidation, or cruel punishment with resulting physical harm, pain, or mental anguish; or"],[2,"(B) deprivation by a person, including a caregiver, of goods or services with intent to cause physical harm, mental anguish, or mental illness."],[0,"(15) Female genital mutilation or cutting"],[1,"The term \"female genital mutilation or cutting\" has the meaning given such term in section 116 of title 18."],[0,"(16) Forced marriage"],[1,"The term \"forced marriage\" means a marriage to which 1 or both parties do not or cannot consent, and in which 1 or more elements of force, fraud, or coercion is present. Forced marriage can be both a cause and a consequence of domestic violence, dating violence, sexual assault or stalking."],[0,"(17) Homeless"],[1,"The term \"homeless\" has the meaning given such term in section 12473 of this title."],[0,"(18) Indian"],[1,"The term \"Indian\" means a member of an Indian tribe."],[0,"(19) Indian country"],[1,"The term \"Indian country\" has the same meaning given such term in section 1151 of title 18."],[0,"(20) Indian housing"],[1,"The term \"Indian housing\" means housing assistance described in the Native American Housing Assistance and Self-Determination Act of 1996 (25 U.S.C. 4101 et seq., as amended)."],[0,"(21) Indian law enforcement"],[1,"The term \"Indian law enforcement\" means the departments or individuals under the direction of the Indian tribe that maintain public order."],[0,"(22) Indian tribe; Indian Tribe"],[1,"The terms \"Indian tribe\" and \"Indian Tribe\" mean a tribe, band, pueblo, nation, or other organized group or community of Indians, including any Alaska Native village or regional or village corporation (as defined in, or established pursuant to, the Alaska Native Claims Settlement Act (43 U.S.C. 1601 et seq.)), that is recognized as eligible for the special programs and services provided by the United States to Indians because of their status as Indians."],[0,"(23) Law enforcement"],[1,"The term \"law enforcement\" means a public agency charged with policing functions, including any of its component bureaus (such as governmental victim services programs or Village Public Safety Officers), including those referred to in section 2802 of title 25."],[0,"(24) Legal assistance"],[0,"(A) Definition"],[2,"The term \"legal assistance\" means assistance provided by or under the direct supervision of a person described in subparagraph (B) to an adult, youth, or child victim of domestic violence, dating violence, sexual assault, or stalking relating to a matter described in subparagraph (C)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/34/12291?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12291. Definitions and grant provisions","tname":"Crime Control and Law Enforcement","by":{"2":"19","3":"56","4":"14"}},{"t":"usc","label":"34 U.S.C. § 30503","url":"https://www.law.cornell.edu/uscode/text/34/30503","subs":["(a)(1)(C)"],"stext":{"head":"§30503. Support for criminal investigations and prosecutions by State, local, and tribal law enforcement officials","paras":[[0,"(a) Assistance other than financial assistance"],[0,"(1) In general"],[1,"At the request of a State, local, or tribal law enforcement agency, the Attorney General may provide technical, forensic, prosecutorial, or any other form of assistance in the criminal investigation or prosecution of any crime that—"],[2,"(A) constitutes a crime of violence;"],[2,"(B) constitutes a felony under the State, local, or tribal laws; and"],[2,"(C) is motivated by prejudice based on the actual or perceived race, color, religion, national origin, gender, sexual orientation, gender identity, or disability of the victim, or is a violation of the State, local, or tribal hate crime laws."],[0,"(2) Priority"],[1,"In providing assistance under paragraph (1), the Attorney General shall give priority to crimes committed by offenders who have committed crimes in more than one State and to rural jurisdictions that have difficulty covering the extraordinary expenses relating to the investigation or prosecution of the crime."],[0,"(b) Grants"],[0,"(1) In general"],[1,"The Attorney General may award grants to State, local, and tribal law enforcement agencies for extraordinary expenses associated with the investigation and prosecution of hate crimes."],[0,"(2) Office of Justice Programs"],[1,"In implementing the grant program under this subsection, the Office of Justice Programs shall work closely with grantees to ensure that the concerns and needs of all affected parties, including community groups and schools, colleges, and universities, are addressed through the local infrastructure developed under the grants."],[0,"(3) Application"],[0,"(A) In general"],[2,"Each State, local, and tribal law enforcement agency that desires a grant under this subsection shall submit an application to the Attorney General at such time, in such manner, and accompanied by or containing such information as the Attorney General shall reasonably require."],[0,"(B) Date for submission"],[2,"Applications submitted pursuant to subparagraph (A) shall be submitted during the 60-day period beginning on a date that the Attorney General shall prescribe."],[0,"(C) Requirements"],[2,"A State, local, and tribal law enforcement agency applying for a grant under this subsection shall—"],[3,"(i) describe the extraordinary purposes for which the grant is needed;"],[3,"(ii) certify that the State, local government, or Indian tribe lacks the resources necessary to investigate or prosecute the hate crime;"],[3,"(iii) demonstrate that, in developing a plan to implement the grant, the State, local, and tribal law enforcement agency has consulted and coordinated with nonprofit, nongovernmental victim services programs that have experience in providing services to victims of hate crimes; and"],[3,"(iv) certify that any Federal funds received under this subsection will be used to supplement, not supplant, non-Federal funds that would otherwise be available for activities funded under this subsection."],[0,"(4) Deadline"],[1,"An application for a grant under this subsection shall be approved or denied by the Attorney General not later than 180 business days after the date on which the Attorney General receives the application."],[0,"(5) Grant amount"],[1,"A grant under this subsection shall not exceed $100,000 for any single jurisdiction in any 1-year period."],[0,"(6) Report"],[1,"Not later than December 31, 2011, the Attorney General shall submit to Congress a report describing the applications submitted for grants under this subsection, the award of such grants, and the purposes for which the grant amounts were expended."],[0,"(7) Authorization of appropriations"],[1,"There is authorized to be appropriated to carry out this subsection $5,000,000 for each of fiscal years 2010, 2011, and 2012."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/34/30503?type=usc&year=mostrecent&link-type=html"},"head":"§30503. Support for criminal investigations and prosecutions by State, local, and tribal law enforcement officials","tname":"Crime Control and Law Enforcement","by":{"2":"18–19","3":"56","4":"14"}},{"t":"usc","label":"42 U.S.C. § 2000e-1","url":"https://www.law.cornell.edu/uscode/text/42/2000e-1","by":{"2":"58"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","subs":["(b)(4)"],"by":{"2":"47"}},{"t":"case","label":"Dillon v. Frank, EEOC Doc. No. 01900157 (Feb. 14 1990)","cite":"1990 WL 1111074","y":1990,"op":1,"sum":"Explaining that sexual-orientation discrimination is “outside the purview of Title VII”.","sumSrc":"brief:2","by":{"2":"22, 26","4":"4, 5"}},{"t":"reg","label":"Executive Orders Exec. Order No. 13087, 63 Fed. Reg. 30,097","url":"https://www.govinfo.gov/link/fr/63/30097","by":{"2":"23"}},{"t":"reg","label":"Exec. Order No. 13672, 79 Fed. Reg. 42,971","url":"https://www.govinfo.gov/link/fr/79/42971","by":{"2":"23"}},{"t":"case","label":"AMTRAK v. Morgan","cite":"536 U.S. 101","y":2002,"id":"2001/00-1614","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964 precludes recovery for discrete acts of discrimination or retaliation that occur outside the statutory time period.","sumSrc":"Oyez","by":{"3":"17, 34"}},{"t":"case","label":"Commod. Futures Trading Comm’n v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"51"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cty. Empls. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"3":"46, 47"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"3":"46"}},{"t":"case","label":"Etsitty v. Utah Transit Auth.","cite":"502 F.3d 1216","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/502/1216/","by":{"3":"35"}},{"t":"case","label":"Glenn v. Brumby","cite":"663 F.3d 1312","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/663/1312/","op":1,"by":{"3":"4"}},{"t":"case","label":"Hamner v. St. Vincent Hosp. & Health Care Ctr., Inc.","cite":"224 F.3d 701","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/224/701/","by":{"3":"16"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharm. USA, Inc.","cite":"139 S. Ct. 628","y":2019,"id":"2018/17-1229","sc":1,"sum":"The sale of an invention to a third party who is obligated to keep the invention confidential may place the invention “on sale” for purposes of the Leahy-Smith America Invents Act, which bars a person from receiving a patent on an invention that was “in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention,” 35 U. S. C. §102(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"3":"52, 53, 54","5":"18, 19"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"3":"43"}},{"t":"case","label":"Higgins v. New Balance Athletic Shoe, Inc.","cite":"194 F.3d 252","y":1999,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/194/252/","op":1,"by":{"3":"16","4":"4"}},{"t":"case","label":"Hopkins v. Baltimore Gas & Elect. Co.","cite":"77 F.3d 745","y":1996,"url":"https://www.courtlistener.com/c/F.3d/77/745/","by":{"3":"16"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Manhattan Properties, Inc. v. Irving Trust Co.","cite":"291 U.S. 320","y":1934,"id":"scdb/1933-048","sc":1,"sum":"1. The claim of a landlord for future rents based on a covenant to p'ay rent in a lease terminated by reintry on the bankruptcy of the tenant, is not a provable debt under § 63 (a) of the Bankruptcy Act. P. 332. So held in view of the great weight of judicial authority construing that section and similar provisions of earlier Acts, and in view of the legislative history of the subject.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"54"}},{"t":"case","label":"MCI Telecomms. Corp. v. AT&T Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"45"}},{"t":"case","label":"Medina v. Income Support Div.","cite":"413 F.3d 1131","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/413/1131/","op":1,"by":{"3":"17, 36","4":"4"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"3":"58"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"51"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"3":"10","4":"12"}},{"t":"case","label":"Sebelius v. Auburn","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"3":"51"}},{"t":"case","label":"United States DOJ v. Landano","cite":"508 U.S. 165","y":1993,"id":"1992/91-2054","sc":1,"sum":"Respondent Landano was convicted in New Jersey state court for murdering a police officer during what may have been a gang-related robbery. In an effort to support his claim in subsequent state-court proceedings that the prosecution violated Brady v. Maryland,373 U. S. 83, by withholding material exculpatory evidence, he filed Freedom of Information Act (FOIA) requests with the Federal Bureau of Investigation …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Walsh v. Friendship Vill. of South Cty.","cite":"352 F. Supp. 3d 920","y":2019,"court":"E.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/352/920/","op":1,"sum":"Rejecting association discrimination claim under Fair Housing Act because such claims are not “actionable with respect to classes unprotected by the statute at issue” and “sexual orientation is one such unprotected class”.","sumSrc":"brief:3","by":{"3":"42"}},{"t":"case","label":"Water Splash, Inc. v. Menon","cite":"137 S. Ct. 1504","y":2017,"id":"2016/16-254","sc":1,"sum":"The Court determined that the Hague Service Convention does not prohibit service of process by mail.","sumSrc":"Oyez","by":{"3":"58"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","subs":["(a)"],"stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1681. Sex","tname":"Education","by":{"3":"56"}},{"t":"usc","label":"29 U.S.C. § 2901","url":"https://www.law.cornell.edu/uscode/text/29/2901","subs":["(b)(4)"],"by":{"3":"56"}},{"t":"usc","label":"42 U.S.C. § 18116","url":"https://www.law.cornell.edu/uscode/text/42/18116","subs":["(a)"],"stext":{"head":"§18116. Nondiscrimination","paras":[[0,"(a) In general"],[0,"Except as otherwise provided for in this title 1 (or an amendment made by this title),1 an individual shall not, on the ground prohibited under title VI of the Civil Rights Act of 1964 (42 U.S.C. 2000d et seq.), title IX of the Education Amendments of 1972 (20 U.S.C. 1681 et seq.), the Age Discrimination Act of 1975 (42 U.S.C. 6101 et seq.), or section 794 of title 29, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under, any health program or activity, any part of which is receiving Federal financial assistance, including credits, subsidies, or contracts of insurance, or under any program or activity that is administered by an Executive Agency or any entity established under this title 1 (or amendments). The enforcement mechanisms provided for and available under such title VI, title IX, section 794, or such Age Discrimination Act shall apply for purposes of violations of this subsection."],[0,"(b) Continued application of laws"],[0,"Nothing in this title 1 (or an amendment made by this title) 1 shall be construed to invalidate or limit the rights, remedies, procedures, or legal standards available to individuals aggrieved under title VI of the Civil Rights Act of 1964 (42 U.S.C. 2000d et seq.), title VII of the Civil Rights Act of 1964 (42 U.S.C. 2000e et seq.), title IX of the Education Amendments of 1972 (20 U.S.C. 1681 et seq.), section 794 of title 29, or the Age Discrimination Act of 1975 [42 U.S.C. 6101 et seq.], or to supersede State laws that provide additional protections against discrimination on any basis described in subsection (a)."],[0,"(c) Regulations"],[0,"The Secretary may promulgate regulations to implement this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18116?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§18116. Nondiscrimination","tname":"The Public Health and Welfare","by":{"3":"56"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(b)","(a)"],"stext":{"head":"§2000e–16. Employment by Federal Government","paras":[[0,"(a) Discriminatory practices prohibited; employees or applicants for employment subject to coverage"],[0,"All personnel actions affecting employees or applicants for employment (except with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units of the Government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on race, color, religion, sex, or national origin."],[0,"(b) Equal Employment Opportunity Commission; enforcement powers; issuance of rules, regulations, etc.; annual review and approval of national and regional equal employment opportunity plans; review and evaluation of equal employment opportunity programs and publication of progress reports; consultations with interested parties; compliance with rules, regulations, etc.; contents of national and regional equal employment opportunity plans; authority of Librarian of Congress"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission shall have authority to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without back pay, as will effectuate the policies of this section, and shall issue such rules, regulations, orders and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the annual review and approval of a national and regional equal employment opportunity plan which each department and agency and each appropriate unit referred to in subsection (a) of this section shall submit in order to maintain an affirmative program of equal employment opportunity for all such employees and applicants for employment;"],[1,"(2) be responsible for the review and evaluation of the operation of all agency equal employment opportunity programs, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each such department, agency, or unit; and"],[1,"(3) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to equal employment opportunity."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. The plan submitted by each department, agency, and unit shall include, but not be limited to—"],[1,"(1) provision for the establishment of training and education programs designed to provide a maximum opportunity for employees to advance so as to perform at their highest potential; and"],[1,"(2) a description of the qualifications in terms of training and experience relating to equal employment opportunity for the principal and operating officials of each such department, agency, or unit responsible for carrying out the equal employment opportunity program and of the allocation of personnel and resources proposed by such department, agency, or unit to carry out its equal employment opportunity program."],[0,"With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil action by employee or applicant for employment for redress of grievances; time for bringing of action; head of department, agency, or unit as defendant"],[0,"Within 90 days of receipt of notice of final action taken by a department, agency, or unit referred to in subsection (a), or by the Equal Employment Opportunity Commission upon an appeal from a decision or order of such department, agency, or unit on a complaint of discrimination based on race, color, religion, sex or national origin, brought pursuant to subsection (a) of this section, Executive Order 11478 or any succeeding Executive orders, or after one hundred and eighty days from the filing of the initial charge with the department, agency, or unit or with the Equal Employment Opportunity Commission on appeal from a decision or order of such department, agency, or unit until such time as final action may be taken by a department, agency, or unit, an employee or applicant for employment, if aggrieved by the final disposition of his complaint, or by the failure to take final action on his complaint, may file a civil action as provided in section 2000e–5 of this title, in which civil action the head of the department, agency, or unit, as appropriate, shall be the defendant."],[0,"(d) Section 2000e–5(f) through (k) of this title applicable to civil actions"],[0,"The provisions of section 2000e–5(f) through (k) of this title, as applicable, shall govern civil actions brought hereunder, and the same interest to compensate for delay in payment shall be available as in cases involving nonpublic parties..1"],[0,"(e) Government agency or official not relieved of responsibility to assure nondiscrimination in employment or equal employment opportunity"],[0,"Nothing contained in this Act shall relieve any Government agency or official of its or his primary responsibility to assure nondiscrimination in employment as required by the Constitution and statutes or of its or his responsibilities under Executive Order 11478 relating to equal employment opportunity in the Federal Government."],[0,"(f) Section 2000e–5(e)(3) of this title applicable to compensation discrimination"],[0,"Section 2000e–5(e)(3) of this title shall apply to complaints of discrimination in compensation under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-16?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–16. Employment by Federal Government","tname":"The Public Health and Welfare","by":{"3":"12","4":"2, 2"}},{"t":"usc","label":"42 U.S.C. § 3604","url":"https://www.law.cornell.edu/uscode/text/42/3604","stext":{"head":"§3604. Discrimination in the sale or rental of housing and other prohibited practices","paras":[[0,"As made applicable by section 3603 of this title and except as exempted by sections 3603(b) and 3607 of this title, it shall be unlawful—"],[0,"(a) To refuse to sell or rent after the making of a bona fide offer, or to refuse to negotiate for the sale or rental of, or otherwise make unavailable or deny, a dwelling to any person because of race, color, religion, sex, familial status, or national origin."],[0,"(b) To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling, or in the provision of services or facilities in connection therewith, because of race, color, religion, sex, familial status, or national origin."],[0,"(c) To make, print, or publish, or cause to be made, printed, or published any notice, statement, or advertisement, with respect to the sale or rental of a dwelling that indicates any preference, limitation, or discrimination based on race, color, religion, sex, handicap, familial status, or national origin, or an intention to make any such preference, limitation, or discrimination."],[0,"(d) To represent to any person because of race, color, religion, sex, handicap, familial status, or national origin that any dwelling is not available for inspection, sale, or rental when such dwelling is in fact so available."],[0,"(e) For profit, to induce or attempt to induce any person to sell or rent any dwelling by representations regarding the entry or prospective entry into the neighborhood of a person or persons of a particular race, color, religion, sex, handicap, familial status, or national origin."],[0,"(f)(1) To discriminate in the sale or rental, or to otherwise make unavailable or deny, a dwelling to any buyer or renter because of a handicap of—"],[1,"(A) that buyer or renter,1"],[1,"(B) a person residing in or intending to reside in that dwelling after it is so sold, rented, or made available; or"],[1,"(C) any person associated with that buyer or renter."],[0,"(2) To discriminate against any person in the terms, conditions, or privileges of sale or rental of a dwelling, or in the provision of services or facilities in connection with such dwelling, because of a handicap of—"],[1,"(A) that person; or"],[1,"(B) a person residing in or intending to reside in that dwelling after it is so sold, rented, or made available; or"],[1,"(C) any person associated with that person."],[0,"(3) For purposes of this subsection, discrimination includes—"],[1,"(A) a refusal to permit, at the expense of the handicapped person, reasonable modifications of existing premises occupied or to be occupied by such person if such modifications may be necessary to afford such person full enjoyment of the premises except that, in the case of a rental, the landlord may where it is reasonable to do so condition permission for a modification on the renter agreeing to restore the interior of the premises to the condition that existed before the modification, reasonable wear and tear excepted.2"],[1,"(B) a refusal to make reasonable accommodations in rules, policies, practices, or services, when such accommodations may be necessary to afford such person equal opportunity to use and enjoy a dwelling; or"],[1,"(C) in connection with the design and construction of covered multifamily dwellings for first occupancy after the date that is 30 months after September 13, 1988, a failure to design and construct those dwellings in such a manner that—"],[2,"(i) the public use and common use portions of such dwellings are readily accessible to and usable by handicapped persons;"],[2,"(ii) all the doors designed to allow passage into and within all premises within such dwellings are sufficiently wide to allow passage by handicapped persons in wheelchairs; and"],[2,"(iii) all premises within such dwellings contain the following features of adaptive design:"],[3,"(I) an accessible route into and through the dwelling;"],[3,"(II) light switches, electrical outlets, thermostats, and other environmental controls in accessible locations;"],[3,"(III) reinforcements in bathroom walls to allow later installation of grab bars; and"],[3,"(IV) usable kitchens and bathrooms such that an individual in a wheelchair can maneuver about the space."],[0,"(4) Compliance with the appropriate requirements of the American National Standard for buildings and facilities providing accessibility and usability for physically handicapped people (commonly cited as \"ANSI A117.1\") suffices to satisfy the requirements of paragraph (3)(C)(iii)."],[0,"(5)(A) If a State or unit of general local government has incorporated into its laws the requirements set forth in paragraph (3)(C), compliance with such laws shall be deemed to satisfy the requirements of that paragraph."],[0,"(B) A State or unit of general local government may review and approve newly constructed covered multifamily dwellings for the purpose of making determinations as to whether the design and construction requirements of paragraph (3)(C) are met."],[0,"(C) The Secretary shall encourage, but may not require, States and units of local government to include in their existing procedures for the review and approval of newly constructed covered multifamily dwellings, determinations as to whether the design and construction of such dwellings are consistent with paragraph (3)(C), and shall provide technical assistance to States and units of local government and other persons to implement the requirements of paragraph (3)(C)."],[0,"(D) Nothing in this subchapter shall be construed to require the Secretary to review or approve the plans, designs or construction of all covered multifamily dwellings, to determine whether the design and construction of such dwellings are consistent with the requirements of paragraph 3(C)."],[0,"(6)(A) Nothing in paragraph (5) shall be construed to affect the authority and responsibility of the Secretary or a State or local public agency certified pursuant to section 3610(f)(3) of this title to receive and process complaints or otherwise engage in enforcement activities under this subchapter."],[0,"(B) Determinations by a State or a unit of general local government under paragraphs (5)(A) and (B) shall not be conclusive in enforcement proceedings under this subchapter."],[0,"(7) As used in this subsection, the term \"covered multifamily dwellings\" means—"],[1,"(A) buildings consisting of 4 or more units if such buildings have one or more elevators; and"],[1,"(B) ground floor units in other buildings consisting of 4 or more units."],[0,"(8) Nothing in this subchapter shall be construed to invalidate or limit any law of a State or political subdivision of a State, or other jurisdiction in which this subchapter shall be effective, that requires dwellings to be designed and constructed in a manner that affords handicapped persons greater access than is required by this subchapter."],[0,"(9) Nothing in this subsection requires that a dwelling be made available to an individual whose tenancy would constitute a direct threat to the health or safety of other individuals or whose tenancy would result in substantial physical damage to the property of others."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3604?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3604. Discrimination in the sale or rental of housing and other prohibited practices","tname":"The Public Health and Welfare","by":{"3":"56"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"3":"48"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"3":"48"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)"],"stext":{"head":"§206. Minimum wage","paras":[[0,"(a) Employees engaged in commerce; home workers in Puerto Rico and Virgin Islands; employees in American Samoa; seamen on American vessels; agricultural employees"],[0,"Every employer shall pay to each of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, wages at the following rates:"],[1,"(1) except as otherwise provided in this section, not less than—"],[2,"(A) $5.85 an hour, beginning on the 60th day after May 25, 2007;"],[2,"(B) $6.55 an hour, beginning 12 months after that 60th day; and"],[2,"(C) $7.25 an hour, beginning 24 months after that 60th day;"],[1,"(2) if such employee is a home worker in Puerto Rico or the Virgin Islands, not less than the minimum piece rate prescribed by regulation or order; or, if no such minimum piece rate is in effect, any piece rate adopted by such employer which shall yield, to the proportion or class of employees prescribed by regulation or order, not less than the applicable minimum hourly wage rate. Such minimum piece rates or employer piece rates shall be commensurate with, and shall be paid in lieu of, the minimum hourly wage rate applicable under the provisions of this section. The Administrator, or his authorized representative, shall have power to make such regulations or orders as are necessary or appropriate to carry out any of the provisions of this paragraph, including the power without limiting the generality of the foregoing, to define any operation or occupation which is performed by such home work employees in Puerto Rico or the Virgin Islands; to establish minimum piece rates for any operation or occupation so defined; to prescribe the method and procedure for ascertaining and promulgating minimum piece rates; to prescribe standards for employer piece rates, including the proportion or class of employees who shall receive not less than the minimum hourly wage rate; to define the term \"home worker\"; and to prescribe the conditions under which employers, agents, contractors, and subcontractors shall cause goods to be produced by home workers;"],[1,"(3) if such employee is employed as a seaman on an American vessel, not less than the rate which will provide to the employee, for the period covered by the wage payment, wages equal to compensation at the hourly rate prescribed by paragraph (1) of this subsection for all hours during such period when he was actually on duty (including periods aboard ship when the employee was on watch or was, at the direction of a superior officer, performing work or standing by, but not including off-duty periods which are provided pursuant to the employment agreement); or"],[1,"(4) if such employee is employed in agriculture, not less than the minimum wage rate in effect under paragraph (1) after December 31, 1977."],[0,"(b) Additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"Every employer shall pay to each of his employees (other than an employee to whom subsection (a)(5) 1 applies) who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this section by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966, title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], or the Fair Labor Standards Amendments of 1974, wages at the following rate: Effective after December 31, 1977, not less than the minimum wage rate in effect under subsection (a)(1)."],[0,"(c) Repealed. Pub. L. 104–188, [title II], §2104(c), Aug. 20, 1996, 110 Stat. 1929"],[0,"(d) Prohibition of sex discrimination"],[0,"(1) No employer having employees subject to any provisions of this section shall discriminate, within any establishment in which such employees are employed, between employees on the basis of sex by paying wages to employees in such establishment at a rate less than the rate at which he pays wages to employees of the opposite sex in such establishment for equal work on jobs the performance of which requires equal skill, effort, and responsibility, and which are performed under similar working conditions, except where such payment is made pursuant to (i) a seniority system; (ii) a merit system; (iii) a system which measures earnings by quantity or quality of production; or (iv) a differential based on any other factor other than sex: Provided, That an employer who is paying a wage rate differential in violation of this subsection shall not, in order to comply with the provisions of this subsection, reduce the wage rate of any employee."],[0,"(2) No labor organization, or its agents, representing employees of an employer having employees subject to any provisions of this section shall cause or attempt to cause such an employer to discriminate against an employee in violation of paragraph (1) of this subsection."],[0,"(3) For purposes of administration and enforcement, any amounts owing to any employee which have been withheld in violation of this subsection shall be deemed to be unpaid minimum wages or unpaid overtime compensation under this chapter."],[0,"(4) As used in this subsection, the term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[0,"(e) Employees of employers providing contract services to United States"],[0,"(1) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof), every employer providing any contract services (other than linen supply services) under a contract with the United States or any subcontract thereunder shall pay to each of his employees whose rate of pay is not governed by chapter 67 of title 41 or to whom subsection (a)(1) of this section is not applicable, wages at rates not less than the rates provided for in subsection (b) of this section."],[0,"(2) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof) and the provisions of chapter 67 of title 41, every employer in an establishment providing linen supply services to the United States under a contract with the United States or any subcontract thereunder shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (b), except that if more than 50 per centum of the gross annual dollar volume of sales made or business done by such establishment is derived from providing such linen supply services under any such contracts or subcontracts, such employer shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (a)(1) of this section."],[0,"(f) Employees in domestic service"],[0,"Any employee—"],[1,"(1) who in any workweek is employed in domestic service in a household shall be paid wages at a rate not less than the wage rate in effect under subsection (b) unless such employee's compensation for such service would not because of section 209(a)(6) of the Social Security Act [42 U.S.C. 409(a)(6)] constitute wages for the purposes of title II of such Act [42 U.S.C. 401 et seq.], or"],[1,"(2) who in any workweek—"],[2,"(A) is employed in domestic service in one or more households, and"],[2,"(B) is so employed for more than 8 hours in the aggregate,"],[0,"shall be paid wages for such employment in such workweek at a rate not less than the wage rate in effect under subsection (b)."],[0,"(g) Newly hired employees who are less than 20 years old"],[0,"(1) In lieu of the rate prescribed by subsection (a)(1), any employer may pay any employee of such employer, during the first 90 consecutive calendar days after such employee is initially employed by such employer, a wage which is not less than $4.25 an hour."],[0,"(2) In lieu of the rate prescribed by subsection (a)(1), the Governor of Puerto Rico, subject to the approval of the Financial Oversight and Management Board established pursuant to section 2121 of title 48, may designate a time period not to exceed four years during which employers in Puerto Rico may pay employees who are initially employed after June 30, 2016, a wage which is not less than the wage described in paragraph (1). Notwithstanding the time period designated, such wage shall not continue in effect after such Board terminates in accordance with section 2149 of title 48."],[0,"(3) No employer may take any action to displace employees (including partial displacements such as reduction in hours, wages, or employment benefits) for purposes of hiring individuals at the wage authorized in paragraph (1) or (2)."],[0,"(4) Any employer who violates this subsection shall be considered to have violated section 215(a)(3) of this title."],[0,"(5) This subsection shall only apply to an employee who has not attained the age of 20 years, except in the case of the wage applicable in Puerto Rico, 25 years, until such time as the Board described in paragraph (2) terminates in accordance with section 2149 of title 48."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§206. Minimum wage","tname":"Labor","by":{"3":"52"}},{"t":"usc","label":"29 U.S.C. § 2601","url":"https://www.law.cornell.edu/uscode/text/29/2601","stext":{"head":"§2601. Findings and purposes","paras":[[0,"(a) Findings"],[0,"Congress finds that—"],[1,"(1) the number of single-parent households and two-parent households in which the single parent or both parents work is increasing significantly;"],[1,"(2) it is important for the development of children and the family unit that fathers and mothers be able to participate in early childrearing and the care of family members who have serious health conditions;"],[1,"(3) the lack of employment policies to accommodate working parents can force individuals to choose between job security and parenting;"],[1,"(4) there is inadequate job security for employees who have serious health conditions that prevent them from working for temporary periods;"],[1,"(5) due to the nature of the roles of men and women in our society, the primary responsibility for family caretaking often falls on women, and such responsibility affects the working lives of women more than it affects the working lives of men; and"],[1,"(6) employment standards that apply to one gender only have serious potential for encouraging employers to discriminate against employees and applicants for employment who are of that gender."],[0,"(b) Purposes"],[0,"It is the purpose of this Act—"],[1,"(1) to balance the demands of the workplace with the needs of families, to promote the stability and economic security of families, and to promote national interests in preserving family integrity;"],[1,"(2) to entitle employees to take reasonable leave for medical reasons, for the birth or adoption of a child, and for the care of a child, spouse, or parent who has a serious health condition;"],[1,"(3) to accomplish the purposes described in paragraphs (1) and (2) in a manner that accommodates the legitimate interests of employers;"],[1,"(4) to accomplish the purposes described in paragraphs (1) and (2) in a manner that, consistent with the Equal Protection Clause of the Fourteenth Amendment, minimizes the potential for employment discrimination on the basis of sex by ensuring generally that leave is available for eligible medical reasons (including maternity-related disability) and for compelling family reasons, on a gender-neutral basis; and"],[1,"(5) to promote the goal of equal employment opportunity for women and men, pursuant to such clause."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/2601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2601. Findings and purposes","tname":"Labor","by":{"3":"48"}},{"t":"law","label":"Pub. L. No. 95-555","url":"https://www.govinfo.gov/link/statute/92/2076","by":{"3":"23"}},{"t":"usc","label":"38 U.S.C. § 4301","url":"https://www.law.cornell.edu/uscode/text/38/4301","by":{"3":"48"}},{"t":"case","label":"Baldwin v. Foxx, EEOC Dec. No. 0120133080","cite":"2015 EEOPUB LEXIS 1905","y":2015,"by":{"3":"52"}},{"t":"case","label":"Dillon v. USPS","cite":"1990 EEOPUB LEXIS 1709","y":1990,"by":{"3":"51"}},{"t":"case","label":"Viveros v. USPS","cite":"1987 EEOPUB LEXIS 1791","y":1987,"by":{"3":"51"}},{"t":"case","label":"Angle v. Veneman, EEOC Decision No. 01A32644","cite":"2004 WL 764265","y":2004,"court":"Apr. 5","sum":"Recognizing that the EEOC had “consistently held that discrimination based on sexual orientation is not actionable under Title VII”.","sumSrc":"brief:4","by":{"4":"5"}},{"t":"case","label":"Doe v. Luzerne County","cite":"660 F.3d 169","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/660/169/","by":{"4":"18"}},{"t":"case","label":"Fisher v. University of Texas","cite":"136 S. Ct. 2198","y":2016,"id":"2015/14-981","sc":1,"sum":"The Court determined that the University of Texas’ use of race as a consideration in the admissions process did not violate the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"4":"28"}},{"t":"case","label":"Furnco Constr. Corp. v. Waters","cite":"438 U.S. 567","y":1978,"id":"1977/77-369","sc":1,"sum":"The Court of Appeals erred in its treatment of the nature of the evidence necessary to rebut a prima facie case under McDonnell Douglas, and in substituting its own judgment as to the proper hiring practices for an employer who claims its hiring practices do not violate Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"16"}},{"t":"case","label":"General Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"4":"32, 33"}},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"4":"15"}},{"t":"case","label":"Marucci v. Caldera, EEOC Decision No. 01982644","cite":"2000 WL 1637387","y":2000,"court":"Oct. 27","by":{"4":"5"}},{"t":"case","label":"Michael M. v. Superior Court","cite":"450 U.S. 464","y":1981,"id":"1980/79-1344","sc":1,"op":8,"sum":"The Court held that the law did not violate the Equal Protection Clause of the Fourteenth Amendment, noting that \"young men and young women are not similarly situated with respect to the problems and the risks of sexual intercourse.\" The Court found that the state had a strong interest in preventing \"illegitimate pregnancy.\" The Court noted that \"[i]t is hardly unreasonable for a legislature acting to protect minor females to exclude them from punishment.","sumSrc":"Oyez","by":{"4":"28, 29"}},{"t":"case","label":"Northern Ins. Co. v. Chatham County","cite":"547 U.S. 189","y":2006,"id":"2005/04-1618","sc":1,"sum":"The Court ruled that Chatham County was not entitled to immunity from suit. The opinion by Justice Clarence Thomas held that since the county was not acting as an \"arm of the state,\" it could not claim 11th Amendment immunity. The Court also refused to recognize a less expansive form of \"residual\" immunity for counties under common law.","sumSrc":"Oyez","by":{"4":"4"}},{"t":"case","label":"Ruth v. Children’s Med. Ctr.","cite":"940 F.2d 662","y":1991,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/940/662/","op":1,"by":{"4":"3"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"4":"27"}},{"t":"case","label":"Wards Cove Packing Co. v. Atonio","cite":"490 U.S. 642","y":1989,"id":"1988/87-1387","sc":1,"op":2,"sum":"Instead, the Court held that \"the proper comparison is generally between the racial composition of the at-issue jobs and the racial composition of the qualified population in the relevant labor market.\" If a substantial difference is found, then the claimants must show that it is the result of a hiring practice of the employer.","sumSrc":"Oyez","by":{"4":"31"}},{"t":"case","label":"Wrightson v. Pizza Hut of Am., Inc.","cite":"99 F.3d 138","y":1996,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/99/138/","op":1,"by":{"4":"4"}},{"t":"case","label":"Young v. United Parcel Serv., Inc.","cite":"135 S. Ct. 1338","y":2015,"id":"2014/12-1226","sc":1,"sum":"The Court held that the Pregnancy Discrimination Act requires courts to consider whether an employer’s policies treat pregnant workers less favorably than non-pregnant workers with similar inabilities to work and whether there are legitimate reasons for such differences.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(2)"],"by":{"4":"32"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"4":"30"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/2096","by":{"4":"14"}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"op":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"22"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"op":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"5":"5, 6"}},{"t":"case","label":"Connecticut Nat. Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"op":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"21"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"5":"19, 20"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"op":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"5":"21"}},{"t":"case","label":"Jama v. Immigration & Customs Enf ’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"5":"19, 20"}},{"t":"case","label":"Jones v. Liberty Glass Co.","cite":"332 U.S. 524","y":1947,"id":"scdb/1947-015","sc":1,"sum":"1. Under § 322 (b) (1) of the Internal Revenue Code, a claim for refund of federal income tax, whether arising out of an income tax \"erroneously or illegally assessed or collected\" or not, must be. filed within three years from the time the return was filed or within two years from the time the tax was paid. The four-year period prescribed by § 3313 is inapplicable to such a claim. Pp. 525-526, 534-535.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"19"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"5":"21"}},{"t":"case","label":"Sessions v. Morales-Santana","cite":"137 S. Ct. 1678","y":2017,"id":"2016/15-1191","sc":1,"op":1,"sum":"The Court held that statutory distinction between the physical presence requirements for transferral of derivative citizenship for unwed citizen mothers and unwed citizen fathers of foreign-born children violates the Equal Protection Clause of the Fifth Amendment, and it is up to Congress, rather than the courts, to create a uniform solution that does not disadvantage any person on the basis of gender.","sumSrc":"Oyez","by":{"5":"10"}},{"t":"case","label":"Smith v. Liberty Mut. Ins. Co.","cite":"569 F.2d 325","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/569/325/","by":{"5":"19"}},{"t":"case","label":"Solid Waste Agency of Northern Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"sum":"The Court held that the provision of the CWA, which requires those discharging fill material into navigable waters to obtain a permit from the Corps, does not extend to isolated, abandoned sand and gravel pits with seasonal ponds, which provide migratory bird habitats.","sumSrc":"Oyez","by":{"5":"17, 21"}},{"t":"case","label":"Sullivan v. Finkelstein","cite":"496 U.S. 617","y":1990,"id":"1989/89-504","sc":1,"op":2,"sum":"The Secretary may immediately appeal a district court order effectively invalidating regulations limiting the kinds of inquiries that must be made to determine entitlement to disability insurance benefits and remanding a claim to the Secretary for consideration without those restrictions. Pp. 623-631. …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"17"}},{"t":"case","label":"United States v. Estate of Romani","cite":"523 U.S. 517","y":1998,"id":"1997/96-1613","sc":1,"op":5,"sum":"Noting that unexpected applications of broad language refect only Congress's “presumed point [to] produce general coverage—not to leave room for courts to recognize ad hoc exceptions”.","sumSrc":"opinion","by":{"5":"22"}},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"op":2,"sum":"Authored by Justice David H. Souter, the Court ruled that the materiality of falsehood is not an element of the crime of knowingly making a false statement to a federally insured bank. Justice Souter wrote for the court that prosecutors need not prove that a lie was relevant enough to affect the outcome of a bank's decision because the law does not require such materiality.","sumSrc":"Oyez","by":{"5":"16"}}]};